import Link from "next/link";
import { getServerSession } from "next-auth";
import { redirect } from "next/navigation";
import { authOptions } from "@/lib/auth";
import { db } from "@/lib/db";
import { Activity, ArrowLeftRight, Bitcoin, CreditCard, FileText, Landmark, ShieldCheck, Users } from "lucide-react";

export default async function Admin() {
	const session = await getServerSession(authOptions);
	if (!session || (session.user as any)?.role !== "ADMIN") redirect("/dashboard");

	const [customers, accounts, transactions, cards, holdings, auditLogs, unreadNotifications] = await Promise.all([
		db.user.count(),
		db.account.count(),
		db.transaction.count(),
		db.virtualCard.count({ where: { status: "ACTIVE" } }),
		db.cryptoHolding.count(),
		db.auditLog.count(),
		db.notification.count({ where: { isRead: false } }),
	]);

	const modules = [
		{ label: "Customers", value: customers, href: "/admin/customers", icon: Users, tone: "indigo" },
		{ label: "Accounts", value: accounts, href: "/admin/customers", icon: Landmark, tone: "emerald" },
		{ label: "Transactions", value: transactions, href: "/admin/audit", icon: ArrowLeftRight, tone: "amber" },
		{ label: "Active cards", value: cards, href: "/admin/customers", icon: CreditCard, tone: "sky" },
		{ label: "Crypto holdings", value: holdings, href: "/admin/customers", icon: Bitcoin, tone: "amber" },
		{ label: "Unread alerts", value: unreadNotifications, href: "/admin/audit", icon: Activity, tone: "red" },
		{ label: "Audit events", value: auditLogs, href: "/admin/audit", icon: FileText, tone: "slate" },
	];

	return <div className="min-h-screen bg-slate-950 text-slate-100"><header className="border-b border-slate-800 bg-slate-950/95"><div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-5 sm:px-8"><Link href="/admin" className="flex items-center gap-2 text-lg font-semibold text-white"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-red-500 text-sm font-black">C</span>Civic<span className="text-red-400">Bank</span><span className="ml-2 rounded-full border border-red-500/20 bg-red-500/10 px-2 py-1 text-[10px] uppercase tracking-wider text-red-300">Admin</span></Link><Link href="/dashboard" className="text-xs font-semibold text-indigo-400 hover:text-indigo-300">Customer view</Link></div></header><main className="mx-auto max-w-7xl space-y-8 p-5 sm:p-8"><div><p className="text-[10px] font-semibold uppercase tracking-[0.18em] text-red-400">Operations control center</p><h1 className="mt-2 text-2xl font-semibold text-white">Manage CivicBank</h1><p className="mt-2 max-w-2xl text-sm text-slate-400">Live operational controls for customers, money movement, card activity, digital assets, notifications, and audit review.</p></div><div className="grid grid-cols-2 gap-4 md:grid-cols-4">{modules.map((module) => { const Icon = module.icon; return <Link key={module.label} href={module.href} className="rounded-2xl border border-slate-800 bg-slate-900 p-5 shadow-xl transition-colors hover:border-indigo-500/40"><div className="flex items-center justify-between"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-slate-950 text-indigo-400"><Icon size={17} aria-hidden="true" /></span><ShieldCheck size={14} className="text-emerald-500" aria-hidden="true" /></div><p className="mt-5 text-xs text-slate-400">{module.label}</p><p className="mt-1 font-mono text-2xl font-semibold text-white">{module.value.toLocaleString()}</p></Link>; })}</div><section className="grid grid-cols-1 gap-5 md:grid-cols-3"><Link href="/admin/customers" className="rounded-2xl border border-indigo-500/20 bg-indigo-500/5 p-5"><p className="text-xs font-semibold text-indigo-300">Customer operations</p><h2 className="mt-2 text-base font-semibold text-white">Review profiles, balances, cards and holdings</h2><p className="mt-2 text-xs text-slate-400">Open the live customer directory and inspect account activity.</p></Link><Link href="/admin/audit" className="rounded-2xl border border-amber-500/20 bg-amber-500/5 p-5"><p className="text-xs font-semibold text-amber-300">Risk and audit</p><h2 className="mt-2 text-base font-semibold text-white">Trace every operational event</h2><p className="mt-2 text-xs text-slate-400">Review transfer, card, account, and crypto activity.</p></Link><Link href="/admin/wallet" className="rounded-2xl border border-slate-800 bg-slate-900 p-5"><p className="text-xs font-semibold text-slate-300">Site controls</p><h2 className="mt-2 text-base font-semibold text-white">Manage product configuration</h2><p className="mt-2 text-xs text-slate-400">Investment and wallet settings remain available from the admin modules.</p></Link></section></main></div>;
}